def transform(grid):
    h,w=len(grid),len(grid[0])
    mask=[[False]*w for _ in range(h)]
    for rh in range(4,h+1):
      for cw in range(4,w+1):
        if rh*cw < 20: continue
        for r in range(h-rh+1):
          for c in range(w-cw+1):
            col=grid[r][c]
            if all(grid[rr][cc]==col for rr in range(r,r+rh) for cc in range(c,c+cw)):
              for rr in range(r,r+rh):
                for cc in range(c,c+cw): mask[rr][cc]=True
    return [[4 if mask[r][c] else grid[r][c] for c in range(w)] for r in range(h)]
